#include <bitset>
#include <iostream>

enum StateFlag { 
    READ_ONLY, 
    HIDDEN, 
    SYSTEM, 
    ARCHIVED, 
    NUM_FLAGS // Used for size N
};

int main() {
    // Size N is 4, matching NUM_FLAGS
    std::bitset<NUM_FLAGS> flags;

    flags.set(READ_ONLY); 
    flags.set(SYSTEM);

    std::cout << "Bitset: " << flags << std::endl;
    // Access using symbolic index
    if (flags[SYSTEM]) {
        std::cout << "System flag is set." << std::endl;
    }
}
